import json,glob
R={}
for f in glob.glob('data/raw/*.jsonl'):
    for l in open(f):
        if l.strip():
            r=json.loads(l); R[r['id']]=r
L=lambda n:R['rec:loan:%04d'%n]
F=lambda n:R['press:fact:%04d'%n]['value']
rl=lambda a,b:['rec:loan:%04d'%i for i in range(a,b+1)]
rf=lambda a,b:['rec:flow:%04d'%i for i in range(a,b+1)]
pf=lambda *n:['press:fact:%04d'%i for i in n]
FXR=6500
def fd(en,es,refs,kind='fact'): return {"text_en":en,"text_es":es,"refs":refs,"kind":kind}

# ---------- computations
B={'mowi':range(1,7),'hendy':range(7,12),'gm':range(12,17),'tuiu':range(17,23),'franede':range(23,30),'aime':range(30,36)}
out={};od={}
for b,rg in B.items():
    o={'USD':0,'PYG':0};d={'USD':0,'PYG':0}
    for n in rg:
        r=L(n)
        if r['outstanding']:
            o[r['currency']]+=r['outstanding']
            if r['kind']=='overdraft': d[r['currency']]+=r['outstanding']
    out[b]=o;od[b]=d
six_usd=sum(o['USD'] for o in out.values()); six_pyg=sum(o['PYG'] for o in out.values())
six=six_usd*FXR+six_pyg
six_od=sum(d['USD'] for d in od.values())*FXR+sum(d['PYG'] for d in od.values())
cap=F(83); PE=cap*5
hendy_tot=252521261384; hendy_inc=73_000_000*12
hendy_int=99587231967*.2415+(5075250*.08+5527500*.075+14627989.28*.08)*FXR
gm_tot=237105585238; gm_inc=10576e6; gm_eq=5327e6
gm_int=(13567500*.08+4321500*.08+5326500*.075)*FXR
fr_tot=314001127279; fr_inc=872e6*12
price=74418418.12; princ=sum(L(n)['principal'] for n in [8,9,11,12,13,14,1,2,4])
new=81841000*FXR+(86.1e9+36.9e9+93e9+64.5e9); rem=price*FXR+118244e6+109668e6+6321573.22*FXR
RWA=PE/0.1385; Dp=1621853458972
r_const=(PE-Dp)/RWA; r_both=(PE-Dp)/(RWA-Dp)
r_red=(PE-Dp-F(126))/RWA; r_trust=(PE-Dp-F(126)-F(265))/RWA
rey=900e6*FXR
D6=(PE-0.06*RWA)/0.94
soft=F(265)+F(266)+F(126)
cov=lambda loss:(F(246)-soft-loss)/F(250)
lst=sum(F(i) for i in range(1,22) if R['press:fact:%04d'%i]['entity']!='org:valores-casa-de-bolsa')
def is_round(v,cur):
    x=v/1.005
    step=50000 if cur=='USD' else 10_000_000
    return abs(x-round(x/step)*step)<0.5
n_amt=[n for n in range(1,41) if L(n)['principal']]
n_round=[n for n in n_amt if is_round(L(n)['principal'],L(n)['currency'])]
print('ops with amounts',len(n_amt),'round+0.5%',len(n_round),n_round)

