ids=set(R)
doc=json.load(open('analysis/fin_credit.json'))
bad=[];n=0
for s in doc['sections']:
    for f in s['findings']:
        n+=1
        assert f['kind'] in('fact','computation','opinion')
        if f['kind']!='opinion' and not f['refs']: bad.append(('norefs',f['text_en'][:40]))
        for r in f['refs']:
            if r not in ids: bad.append((s['id'],r))
        assert f['text_en'] and f['text_es']
for m in doc['metrics']:
    for i in m['inputs']:
        if i['ref'] not in ids: bad.append(('metric',i['ref']))
for o in doc['opinions']:
    for r in o['basis_refs']:
        if r not in ids: bad.append(('opinion',r))
print('findings',n,'metrics',len(doc['metrics']),'opinions',len(doc['opinions']),'unresolved',bad)
